<?php
namespace Modules\Ran\Services;
use DomainException;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\Transfer;use Modules\Ran\Entities\StockLot;use Modules\Ran\Support\RanContext;
class TransferService {public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private AuditService $audit){}
 public function create(array $data):Transfer{return DB::transaction(function()use($data){$transfer=Transfer::create(['business_id'=>RanContext::businessId(),'transfer_no'=>$this->numbers->next('transfer',(int)$data['from_location_id']),'transfer_date'=>$data['transfer_date'],'from_location_id'=>$data['from_location_id'],'from_store_id'=>$data['from_store_id'],'to_location_id'=>$data['to_location_id'],'to_store_id'=>$data['to_store_id'],'status'=>'draft','notes'=>$data['notes']??null]);foreach($data['lines'] as $line){$lot=StockLot::findOrFail($line['stock_lot_id']);if((int)$lot->location_id!==(int)$data['from_location_id']||(int)$lot->store_id!==(int)$data['from_store_id'])throw new DomainException('Selected stock lot does not belong to the source location and store.');$transfer->lines()->create(['business_id'=>RanContext::businessId(),'stock_lot_id'=>$lot->id,'item_id'=>$lot->item_id,'quantity'=>$line['quantity'],'weight'=>$line['weight'],'notes'=>$line['notes']??null]);}$this->audit->record('created',$transfer);return $transfer->load('lines.stockLot.item');});}
 public function dispatch(Transfer $transfer):Transfer{if($transfer->status!=='draft')throw new DomainException('Only draft transfers can be dispatched.');return DB::transaction(function()use($transfer){$transfer->load('lines.stockLot');foreach($transfer->lines as $line)$this->inventory->issue($line->stockLot,(float)$line->quantity,(float)$line->weight,['reference_type'=>'transfer','reference_id'=>$transfer->id,'reference_no'=>$transfer->transfer_no,'description'=>'Transfer dispatched']);$transfer->update(['status'=>'in_transit','dispatched_by'=>RanContext::userId(),'dispatched_at'=>now()]);$this->audit->record('dispatched',$transfer);return $transfer;});}
 public function receive(Transfer $transfer):Transfer{if($transfer->status!=='in_transit')throw new DomainException('Only in-transit transfers can be received.');return DB::transaction(function()use($transfer){$transfer->load('lines.stockLot');foreach($transfer->lines as $line){$source=$line->stockLot;$received=$this->inventory->receive(['item_id'=>$line->item_id,'location_id'=>$transfer->to_location_id,'store_id'=>$transfer->to_store_id,'quantity'=>$line->quantity,'gross_weight'=>$line->weight,'net_weight'=>$line->weight,'fine_weight'=>0,'unit_cost'=>$source->unit_cost,'total_cost'=>(float)$source->unit_cost*max((float)$line->quantity,1),'sale_price'=>$source->sale_price,'serial_no'=>$source->serial_no,'rfid_tag'=>$source->rfid_tag,'source_type'=>'transfer','source_id'=>$transfer->id,'reference_no'=>$transfer->transfer_no,'description'=>'Transfer received']);$line->update(['received_quantity'=>$line->quantity,'received_weight'=>$line->weight]);}$transfer->update(['status'=>'received','received_by'=>RanContext::userId(),'received_at'=>now()]);$this->audit->record('received',$transfer);return $transfer;});}}
